public class Pet {
    private String petName;
    private int petAge;
    private double petWeight;

    // default constructor, has no parameters
    public Pet() {
        petName = "No name yet";
        petAge = 0;
        petWeight = 0;
    }

    // initializes name of pet only
    public Pet(String initialName) {
        petName = initialName;
        petAge = 0;
        petWeight = 0;
    }

    // initializes age of pet only
    public Pet(int initialAge) {
        petName = "No name yet";
        petAge = initialAge;
        petWeight = 0;
    }

    // initializes weight of pet only
    public Pet(double initialWeight) {
        petName = "No name yet";
        petAge = 0;
        petWeight = initialWeight;
    }

    // initializes name, age, and weight of pet
    public Pet(String initialName, int initialAge, double initialWeight) {
        petName = initialName;
        petAge = initialAge;
        petWeight = initialWeight;
    }

    public void display() {
        System.out.printf("%s, age %d, weight %.1f kg%n", petName, petAge, petWeight);
    }
}

public class PetDemo {
    public static void main(String[] args) {
        new Pet().display();
        new Pet("Bantay").display();
        new Pet(3).display();
        new Pet(12.5).display();
        new Pet("Muning", 2, 4.3).display();
    }
}

